class Solution { public:
 int countOfPairs(vector<int>& nums){const int MOD=1000000007;int mx=*max_element(nums.begin(),nums.end());vector<int> dp(mx+1),next(mx+1),pref(mx+1);
 for(int a=0;a<=nums[0];++a)dp[a]=1;
 for(int i=1;i<(int)nums.size();++i){pref[0]=dp[0];for(int a=1;a<=mx;++a)pref[a]=(pref[a-1]+dp[a])%MOD;
  fill(next.begin(),next.end(),0);for(int a=0;a<=nums[i];++a){int bound=min(a,a+nums[i-1]-nums[i]);if(bound>=0)next[a]=pref[bound];}dp.swap(next);
 }int ans=0;for(int x:dp)ans=(ans+x)%MOD;return ans;}
};
